<script setup lang="ts">
import {computed,ref} from 'vue'
import {X,Plus} from 'lucide-vue-next'
const props=withDefaults(defineProps<{modelValue:string[];suggestions?:string[];label:string;placeholder?:string;tags?:boolean;disabled?:boolean}>(),{suggestions:()=>[],tags:true,disabled:false})
const emit=defineEmits<{ 'update:modelValue':[value:string[]] }>()
const text=ref(''),inputId='tokens-'+crypto.randomUUID()
const candidates=computed(()=>props.suggestions.filter(s=>!props.modelValue.includes(s)&&(!text.value||s.toLowerCase().includes(text.value.toLowerCase()))).slice(0,8))
function add(value=text.value){const values=value.split(/[,，;；\n]+/).map(v=>v.trim()).map(v=>props.tags?v.replace(/^#+/,'').trim().toLowerCase():v).filter(Boolean);emit('update:modelValue',[...new Set([...props.modelValue,...values])].slice(0,30));text.value=''}
function remove(value:string){emit('update:modelValue',props.modelValue.filter(v=>v!==value))}
</script>
<template><div class="token-field"><label :for="inputId">{{label}}</label><div class="token-box"><span v-for="value in modelValue" :key="value" class="token sensitive">{{tags?'#':''}}{{value}}<button type="button" :aria-label="'移除'+value" :disabled="disabled" @click="remove(value)"><X :size="12"/></button></span><input :id="inputId" v-model="text" :disabled="disabled" :placeholder="placeholder||(tags?'输入标签，回车添加':'输入姓名，回车添加')" maxlength="80" @keydown.enter.prevent="add()" @keydown="e=>{if(e.key===','||e.key==='，'){e.preventDefault();add()}}" @blur="text.trim()&&add()"/><button v-if="text.trim()" type="button" title="添加" :disabled="disabled" @mousedown.prevent="add()"><Plus :size="15"/></button></div><div v-if="candidates.length" class="token-suggestions"><button v-for="item in candidates" :key="item" type="button" :disabled="disabled" @mousedown.prevent="add(item)">{{tags?'#':''}}{{item}}</button></div></div></template>
<style scoped>.token-field{min-width:0;margin:0 0 15px}.token-field>label{display:block;font-size:11px;color:var(--muted);margin-bottom:8px}.token-box{display:flex;gap:6px;align-items:center;flex-wrap:wrap;min-height:41px;border:1px solid var(--border);border-radius:8px;padding:7px 9px;background:var(--input)}.token{display:inline-flex;align-items:center;gap:5px;background:var(--mint-bg);border:1px solid #96cbae28;border-radius:5px;color:var(--mint);font-size:11px;padding:4px 6px;max-width:100%;overflow-wrap:anywhere}.token-box button{display:inline-flex;border:0;background:none;color:inherit;padding:0;cursor:pointer}.token-box input{width:140px;flex:1;min-width:90px;background:none;border:0;outline:none;color:var(--text);font:inherit;font-size:12px;padding:3px}.token-suggestions{display:flex;gap:5px;flex-wrap:wrap;margin-top:6px}.token-suggestions button{font-size:10px;color:var(--muted);border:0;border-radius:5px;background:var(--panel-soft);padding:4px 7px;cursor:pointer}.token-suggestions button:hover{color:var(--mint)}.token-box:focus-within{border-color:var(--mint)}</style>
